export type ArticleDepth = { heading: string; paragraphs: string[] };

// Individually written additions, keyed by the exact editorial intent.
const prose: Record<string, [string, string]> = {
  "vad-ar-rcs": ["Vad märker mottagaren?", "Du kan börja ett samtal i den vanliga inkorgen och ändå få olika funktioner beroende på vem du skriver till. Därför är RCS bäst förstått som sättet meddelandet transporteras och visas, inte som en ny kontaktlista. För företag tillkommer en registrerad profil och ett system som hanterar utskick och svar. Kunden behöver inte installera företagets egen app för att läsa meddelandet."],
  "rcs-vs-sms": ["Välj kanal efter uppgiften", "Ett kort besked utan bild eller svarsalternativ kan fungera bra som SMS. RCS blir mer intressant när kunden behöver se något eller göra ett tydligt val direkt i meddelandet. Jämför därför samma uppgift i båda kanalerna. Om RCS-versionen visar tre produkter behöver SMS-versionen kanske länka till en sida där samma produkter kan jämföras, inte försöka återge hela karusellen i text."],
  "rcs-for-foretag": ["Kanalen behöver ett sammanhang", "Ett företagsmeddelande är användbart när det hör ihop med något kunden redan förstår: en beställning, en bokning eller en fråga. Planera även vem som äger nästa steg. Ett svar om ändrad leverans ska nå leveranshanteringen, inte fastna i en separat inkorg. Att välja RCS löser visningen i telefonen; rutinen bakom beskedet avgör om kunden faktiskt får hjälp."],
  "verifierad-avsandare": ["Igenkänning utan falsk trygghet", "Profilens namn bör vara det kunden känner igen från köpet. Ett okänt koncernnamn kan skapa osäkerhet även när det är korrekt registrerat. Håll logotyp, kontaktvägar och länkdomäner konsekventa. Om varumärket ändras behöver uppgifterna ses över med partnern. Kunden ska kunna kontrollera avsändaren genom en oberoende kontaktväg, särskilt när meddelandet gäller pengar eller kontouppgifter."],
  "rich-cards-karuseller": ["Ett val per kort", "En karusell fungerar bäst när korten följer samma struktur: bild, begripligt namn, relevant uppgift och nästa steg. Om varje kort har ett nytt upplägg blir alternativen svårare att jämföra. Ett ensamt rich card är ofta bättre för en leverans eller bokning. Börja med innehållet kunden behöver, och lägg bara till fler kort när de representerar verkliga alternativ."],
  "rcs-api-webhooks": ["Två riktningar i samma flöde", "Utskicket och svaret lever olika länge. Ett orderprogram kan begära meddelandet nu medan telefonens leveransrapport kommer senare. Integrationen behöver därför kunna hitta samma order utan att det ursprungliga anropet fortfarande är öppet. Beskriv vad varje status får ändra och vad som ska hända om en händelse saknas. Det gör felsökningen betydligt tydligare än en enda etikett som säger skickat."],
  "rcs-pa-iphone": ["Testa ett verkligt samtal", "När inställningen finns, öppna en konversation med någon som har bekräftat RCS och kontrollera kanaltexten innan du skickar. Ett lyckat bildmeddelande är inte ensamt bevis eftersom även MMS kan bära bilder. Om RCS saknas, notera iOS-version och vilken linje som används. För en företagsavsändare krävs dessutom ett separat test från just den agenten, inte bara mellan två privata telefoner."],
  "rcs-pa-android": ["App, nummer och anslutning", "En telefon kan ha flera meddelandeappar, men det är inställningarna i den app som används som är relevanta. Kontrollera att rätt nummer står under RCS-chattar och att anslutningen är klar. Om ett visst samtal fortfarande går som SMS kan problemet finnas hos mottagaren. Ändra inte hela telefonens konfiguration bara för att en kontakt saknar stöd."],
  "aktivera-rcs": ["När aktivering inte räcker", "Skilj mellan att funktionen är påslagen och att registreringen är färdig. Ett verifieringsläge betyder att appen fortfarande försöker knyta tjänsten till numret. Läs den aktuella statusen innan du testar igen. Upprepade av- och påslag ger inget tydligt felsökningsunderlag. När anslutningen väl är klar behöver även den andra deltagaren ha stöd för att samtalet ska använda RCS."],
  "vad-kostar-rcs": ["Räkna på det som ska skickas", "Två projekt med samma antal kunder kan ha olika kostnad om det ena skickar ett besked och det andra flera uppföljningar. Gör därför budgeten utifrån meddelanden, inte bara kontaktlistans storlek. Skilj också kanalens pris från arbetet med att ta fram innehåll och ansluta ordersystem. En eventuell reservkanal ska räknas separat så att kostnaden inte döljs i ett genomsnitt."],
  "ar-rcs-sakert": ["Bedöm hela informationsvägen", "En länk kan leda från meddelandet till en webbplats där kunden loggar in. Då är även webbplatsens säkerhet och rättigheterna i företagets system viktiga. Begränsa information som syns på låsskärmen och undvik att göra chatten till förvaring för känsliga dokument. Fråga leverantören vilket skydd som gäller för just företagsmeddelanden och lagrade kundsvar, i stället för att nöja er med ordet krypterat."],
  "rcs-historia": ["Varför införandet sker i etapper", "En standard blir användbar först när nät, appar och avsändartjänster stöder den. De delarna uppdateras inte samtidigt, vilket förklarar varför en lansering i ett land inte automatiskt säger något om ett annat. Historiken hjälper att förstå skillnaderna, men är ingen tillgänglighetslista. Vid inköp är det bättre att be om ett aktuellt räckviddstest än att utgå från ett gammalt lanseringsår."],
  "universal-profile": ["Version är inte samma sak som räckvidd", "Två tjänster kan hänvisa till Universal Profile men ändå ha olika införda funktioner. Det kan märkas på media, knappar eller hur en konversation visas. När en leverantör beskriver standardstöd behöver frågan därför följas av vad som faktiskt fungerar för era mottagare. Ett praktiskt test av det planerade innehållet ger mer användbar information än ett versionsnummer utan förklaring."],
  "rcs-wifi-mobildata": ["Uppkoppling och aktualitet", "Ett meddelande kan bli liggande medan telefonen saknar internet. När anslutningen återkommer kan innehållet redan vara inaktuellt, exempelvis en påminnelse om en tid som passerat. För tidskänsliga företagsbesked behöver ni bestämma hur länge informationen är användbar. Ett wifi-test visar att uppkopplingen fungerar just då, men säger inte hur leveransen beter sig när kunden senare är offline."],
  "rcs-myter": ["Granska vad ett påstående avser", "När någon säger att RCS finns på alla nya telefoner saknas ofta flera förutsättningar: app, operatör, inställning och företagsavsändare. Be om ett konkret användningsfall innan påståendet blir en planeringsgrund. Samma sak gäller resultat som högre klickfrekvens. Ett enskilt kampanjutfall är inte en egenskap hos standarden och behöver beskrivas med målgrupp, jämförelse och mätmetod."],
  "rcs-ordforklaring-pa-svenska": ["Översätt till vad som händer", "Tekniska ord blir lättare att förstå när de kopplas till en handling. Agenten är den kunden ser som avsändare, kortet är innehållet och webhooken är vägen tillbaka till företagets system. Postback-data hjälper systemet att känna igen ett val. De delarna kan användas tillsammans, men de ersätter inte varandra. En snygg profil säger exempelvis inget om hur ett inkommande kundsvar hanteras."],
  "rcs-marknadsforing": ["Från erbjudande till resultat", "Bestäm om målet är ett sidbesök, en bokning eller ett köp innan meddelandet utformas. En knapp som öppnar kampanjsidan ska följas av en sida där erbjudandet fortfarande gäller och går att genomföra. Om kunden behöver leta efter samma produkt igen har meddelandet bara flyttat friktionen. Utvärdera hela vägen och håll slutsatserna till det ni faktiskt har mätt."],
  "rcs-e-handel": ["Låt ordern styra beskedet", "Utskicket bör utgå från en bestämd händelse i orderflödet. Om en order delas i flera paket behöver kunden förstå vilken del beskedet gäller. Det är också viktigt att gamla statusar inte skrivs över av senare inkomna meddelandehändelser. RCS kan göra informationen lättare att läsa, men riktigheten kommer från order- och leveranssystemen som matar flödet."],
  "rcs-kundservice": ["Svar behöver en ägare", "En kund som skriver i chatten väntar sig att frågan kommer fram till någon. Ange därför vad som händer utanför bemannad tid och låt pågående ärenden följa med till personalen. Om kunden redan förklarat problemet ska överlämningen inte kräva samma berättelse igen. Mät gärna tiden till ett meningsfullt svar, inte bara hur snabbt ett automatiskt mottagningsbesked skickas."],
  "rcs-bokningspaminnelser": ["Bekräftelse och ändring är olika saker", "En knapp som bekräftar närvaro kan hanteras direkt om bokningssystemet stöder det. Ombokning kan däremot kräva nya val eller ett beslut från personal. Skriv den skillnaden tydligt i beskedet efter knapptrycket. Om en bokning hinner ändras ska nästa meddelande använda den nya tiden, inte en kopia av informationen som fanns när påminnelsen schemalades."],
  "rcs-leveransnotiser": ["Flera besked om samma leverans", "Kunden behöver inte få ett nytt meddelande för varje intern statusändring. Välj händelser som ändrar vad kunden behöver veta eller göra. Ett besked om försening är exempelvis användbart om det visar ett nytt tidsfönster och en fungerande kontaktväg. Koppla meddelandet till leveransreferensen så att ett klick öppnar rätt försändelse även när kunden har flera beställningar."],
  "rcs-restaurang-cafe": ["Gör bokningen lätt att hitta", "En gäst på väg till restaurangen har större nytta av tid, adress och kontaktväg än av flera menybilder. Lägg det viktigaste först och låt en karta eller bokningslänk komplettera texten. Om någon svarar med allergifrågor eller ändrat sällskap behöver restaurangen ha en rutin för det. Ett rikt meddelande ska inte bjuda in till svar som ingen sedan läser."],
  "rcs-gdpr-samtycke": ["Skilj på ändamålen", "Samma telefonnummer kan finnas i både ett bokningsregister och en kampanjlista utan att användningen är densamma. Dokumentera varför uppgiften behövs i respektive flöde och hur mottagarens val slår igenom. En teknisk leveranskvittens kan användas för felsökning men ska inte automatiskt bli ett nytt marknadsföringsunderlag. Bedömning av rättslig grund, information och kontaktregler måste göras för den verkliga behandlingen."],
  "rcs-roi": ["Resultat behöver en jämförelse", "Om en kampanj ger fler bokningar behöver ni veta vad som skulle ha hänt utan den. En jämförbar kontrollgrupp eller ett genomtänkt test kan ge bättre stöd än att jämföra två olika säsonger. Kostnader och intäkter ska avse samma period. Räkna inte varje klick som en kund eller varje bokning som intäkt om avbokningar och återbetalningar ännu inte är kända."],
  "rcs-kampanjplan": ["Planera nästa steg före utskicket", "Ett meddelande kan vara färdigt medan kampanjen ändå inte är redo. Landningssidan måste kunna hantera trafiken och personalen måste veta hur kundsvar tas om hand. Bestäm också vem som får pausa utskicket om något blir fel. Då kan ett litet första test användas för att upptäcka verkliga problem i flödet, inte bara för att bedöma hur bilden ser ut."],
  "rcs-tonalitet": ["Var konkret även när något går fel", "Ett servicebesked behöver inte låta stelt, men vänligheten ska inte dölja informationen. Om en leverans är försenad är en tydlig ny tidsuppgift bättre än en lekfull formulering om tålamod. Undvik att kalla en begäran klar när den fortfarande väntar. Samma princip gäller knappar, automatiska svar och meddelanden från personal: kunden ska förstå vad som faktiskt har hänt."],
  "rcs-basic-single-conversation": ["Utgå från det verkliga innehållet", "Börja med att rita kundens flöde: ett kort besked, ett rikt utskick eller ett samtal med flera steg. Fråga sedan hur leverantören klassificerar varje del. Namnen ska inte behandlas som nivåer där dyrast alltid är bäst. En enkel orderstatus kan klara sig med text, medan ett produktval behöver media. Debiteringsreglerna måste bekräftas separat från de tekniska möjligheterna."],
  "foreslagna-svar": ["Ett val måste betyda något bestämt", "Svarsalternativen bör vara möjliga att hantera utan att gissa. Ja blir otydligt om meddelandet innehåller flera frågor, medan Bekräfta närvaro har ett bestämt syfte. Knyt valet till rätt ärende och ge kunden en bekräftelse som motsvarar systemets verkliga resultat. Om bokningen inte kan ändras automatiskt ska svaret beskriva en mottagen begäran, inte en färdig ändring."],
  "rcs-bilder-video": ["Mediet ska hjälpa beskedet", "Produktbilder behöver visa det kunden ska bedöma, medan en instruktionsfilm behöver göra en uppgift lättare. Viktig information får inte bli beroende av att kunden kan spela upp ljud eller vänta på en stor fil. Testa även långsam anslutning och skriv en begriplig textdel. Bildens beskärning och videons första bild påverkar vad som faktiskt syns innan kunden väljer att öppna innehållet."],
  "skriva-bra-rcs-meddelanden": ["Ta bort allt som inte behövs för valet", "Läs meddelandet som en kund som inte sett er interna plan. Går det att förstå vilken order eller bokning det gäller och vart knappen leder? Förkorta inledningar innan ni tar bort villkor eller viktiga tidsuppgifter. Ett kort meddelande är inte automatiskt tydligt. Målet är att kunden ska kunna agera utan att behöva gissa eller kontakta supporten för grundläggande information."],
  "lankar-och-knappar": ["Knappen och målsidan hör ihop", "En knapp till en order bör öppna ordern eller en tydlig inloggning som leder vidare till den. Om den bara öppnar startsidan måste kunden göra arbetet igen. Prova länken i telefonens webbläsare och kontrollera vad som händer när sessionen saknas. Bekräftelsen på målsidan ska visa att handlingen slutförts; att meddelandeappen öppnat länken räcker inte."],
  "rcs-fallback-sms": ["Bevara beskedet, inte formen", "Reservtexten ska hjälpa kunden att göra samma viktiga sak även när bilder och knappar saknas. En spårningslänk kan ersätta ett leveranskort, men flera erbjudanden kan kräva en samlad sida. Testa SMS-versionen som ett eget meddelande. Tidsgräns, kostnad och hantering av sent levererat RCS behöver ingå i samma plan så att reserven inte skapar fler problem än den löser."],
  "rcs-leveransstatus": ["Spara både händelse och sammanhang", "En statusrapport blir mer användbar om den har meddelande-id och tidpunkt. Då går det att skilja lång väntan från ett snabbt fel och se vilken kanal som till slut användes. Visa inte läst som en juridisk bekräftelse eller levererat som ett genomfört kundärende. Om uppföljningen kräver en bokning eller ett svar behöver den händelsen komma från rätt system."],
  "testa-rcs-utskick": ["Testa även det som inte ska hända", "Försök bekräfta samma bokning två gånger, öppna en gammal länk och svara efter att ärendet stängts. Sådana tester visar om flödet skyddar kunden från dubbla eller felaktiga ändringar. Använd också telefoner med olika textstorlek och en mottagare utan RCS-stöd. Det viktiga är inte att alla tester ser perfekta ut, utan att varje avvikelse får ett begripligt och säkert resultat."],
  "kapabilitetskontroll": ["Använd svaret för innehållsval", "En kontroll kan ge underlag för att välja karusell, enklare kort eller annan kanal. Spara vilken agent och vilken funktion kontrollen avsåg, annars kan resultatet bli missvisande när ni byter avsändare. Följ tjänstens aktualitetsregler och kontrollera fel separat från ett negativt stödsvar. Ett tillfälligt tekniskt fel ska inte utan vidare tolkas som att kunden aldrig kan nås med RCS."],
  "rcs-agent-registrering": ["Förbered uppgifter som håller ihop", "Varumärkesnamn, logotyp och kontaktuppgifter ska gå att känna igen från företagets andra kanaler. Utse någon som kan bekräfta partnerns behörighet och håll personen tillgänglig under processen. Fråga vad som återstår efter verifieringen och vilka marknader lanseringen gäller. En profil som ser färdig ut i ett verktyg är inte bevis på att publika meddelanden kan skickas till kunder."],
  "begrepp-agent": ["Avsändaren och systemet bakom", "Agenten ger företaget en identitet i meddelandekanalen. Vad den skickar bestäms däremot av en människa, ett webbverktyg eller ett anslutet system. Samma agent kan därför användas för enkla besked utan AI. Vid fel behöver man skilja ett problem med avsändarens lansering från ett problem i systemet som försöker skicka meddelandet."],
  "begrepp-agentprofil": ["Profilen är kundens orientering", "Namn och logotyp visar vem samtalet gäller, medan kontaktuppgifter hjälper kunden att kontrollera eller följa upp beskedet. Profilen bör därför skötas som en annan publik företagsuppgift. Om en supportadress slutar fungera hjälper det inte att logotypen fortfarande är rätt. Ändringar ska stämmas av med partnern eftersom registrering och godkännande kan påverkas."],
  "begrepp-api": ["Ett anrop är början, inte slutet", "Ett API gör att program kan begära en handling utan att någon fyller i ett webbformulär. Vid RCS-utskick behöver anropet innehålla mottagare och rätt innehåll enligt leverantörens regler. Programmet måste också hantera fel och senare statusar. En anslutning som bara kan skicka men inte följa upp leveransen ger ett ofullständigt underlag för drift och kundservice."],
  "begrepp-asynkron-leverans": ["Därför kommer svaret senare", "Telefonen kan vara offline när företaget skickar. Tjänsten behöver då rapportera vad som hände när leveransen avgjorts, inte låta det ursprungliga anropet vänta tills kunden är tillbaka. Integrationen behöver känna igen meddelandet även vid senare händelser. Det är samma princip som när ett ordernummer används för att följa en leverans långt efter att beställningen gjordes."],
  "begrepp-brand-verification": ["Vad kontrollen inte säger", "Verifieringen knyter företagsidentiteten till den som får administrera avsändaren. Den bedömer inte om nästa kampanj har rätt pris eller om varje mottagare får kontaktas. Företaget ansvarar fortfarande för innehåll och regler. Efter en godkänd verifiering kan lanseringssteg återstå, så kontrollera statusen innan ett publikt utskick planeras."],
  "begrepp-foreslagen-atgard": ["En åtgärd kan lämna samtalet", "När kunden trycker på en webblänk fortsätter uppgiften ofta i webbläsaren. Där kan inloggning, val eller betalning återstå. Knappens namn bör beskriva det närmaste steget och inte lova ett färdigt resultat. Kontrollera även vad mottagarens app stöder. En åtgärd som ser bra ut i förhandsvisningen kan behöva en enklare reservväg på andra telefoner."],
  "begrepp-karusell": ["När flera kort hjälper", "Karusellen gör alternativen synliga i samma meddelande, men allt syns inte samtidigt på skärmen. Kunden måste bläddra för att se senare kort. Lägg därför sammanhanget först och använd samma slags uppgifter på varje alternativ. Om ordningen bär en viktig instruktion bör den också förklaras i text; utgå inte från att alla sveper genom hela innehållet."],
  "begrepp-leveranskvittens": ["Ett tekniskt steg i kundresan", "Kvittensen hjälper till att skilja ett meddelande som nått enheten från ett som fortfarande väntar eller fått fel. Den kan användas för driftuppföljning och kanalval. Kunden kan ändå ha missat notisen eller ännu inte öppnat samtalet. En genomförd betalning eller ändrad bokning behöver därför sin egen bekräftelse och ska inte härledas från leveransstatusen."],
  "begrepp-laskvitto": ["Läsning är inte en affärshändelse", "En läsrapport säger något om hur appen rapporterat meddelandets status, inte varför kunden öppnade det eller vad personen gjorde efteråt. Använd den som ett steg i analysen och redovisa hur måttet definieras. Saknade rapporter behöver hållas åtskilda från bekräftat olästa meddelanden. Annars kan både läsandel och jämförelser mellan kanaler ge en felaktig bild."],
  "begrepp-maap": ["Infrastrukturen syns inte i inkorgen", "Kunden möter en företagsprofil och ett meddelande, inte plattformslagret bakom dem. MaaP beskriver hur företagskommunikation kan stödjas i ekosystemet. När en leverantör använder ordet bör ni fråga vilka konkreta funktioner som ingår: avsändarhantering, utskick, inkommande svar eller rapporter. Själva förkortningen säger inget säkert om tjänstens räckvidd eller debitering."],
  "begrepp-mms": ["Bildstöd är inte samma format", "MMS kan bära media men har inte samma strukturerade kort och svarsalternativ som företags-RCS. Därför är ett foto i inkorgen inte tillräckligt för att avgöra kanalen. Operatörens och telefonens förutsättningar påverkar även MMS. Om ni väljer MMS som reserv behöver innehållet testas i det formatet, inte bara kopieras från ett rikt RCS-kort."],
  "begrepp-operator": ["Nät och abonnemang är olika uppgifter", "Ett mobilvarumärke kan använda ett annat företags nät utan att alla tjänster och inställningar blir identiska. Fråga därför den operatör som ansvarar för ditt abonnemang. För iPhone är uttryckligt RCS-stöd särskilt relevant. För ett företagsutskick behöver avsändarens partner dessutom kontrollera att den registrerade agenten kan nå telefonnumret, oavsett nätets allmänna RCS-information."],
  "begrepp-p2p": ["Privat samtal, andra förutsättningar", "P2P beskriver deltagarna, inte en särskild kampanjfunktion. Två personer kan chatta i sina meddelandeappar utan den agentregistrering som företags-RCS använder. Uppgifter om läskvitton eller kryptering behöver läsas i det sammanhanget. Ett test mellan kollegornas telefoner är användbart för privat chatt men visar inte om företagets kommande avsändare är lanserad eller når samma nummer."],
  "begrepp-postback-data": ["Låt systemet läsa ett stabilt val", "Texten på en knapp kan ändras mellan språk eller kampanjer. Datan bakom valet bör däremot kunna identifiera samma handling och rätt ärende. Knyt den till en referens och kontrollera att ärendet fortfarande får ändras när svaret kommer. Ett gammalt knapptryck ska inte kunna bekräfta en bokning som redan avbokats eller tillhör en annan kund."],
  "begrepp-rbm": ["Företagsdelen av RCS", "RBM omfattar mer än att lägga en bild i ett privat meddelande. Företaget använder en registrerad identitet och behöver hantera utskick, kundsvar och statusar genom en tjänst. Hur detta erbjuds varierar mellan leverantörer. Be därför om konkret information om lansering, räckvidd och vad som händer när en mottagare inte kan nås, snarare än att bedöma tjänsten utifrån förkortningen."],
  "begrepp-rcs-chatt": ["Samma inkorg kan byta kanal", "Det är meddelandets kanal, inte kontaktens namn, som avgör vilka funktioner som finns. Ett samtal kan använda RCS när förutsättningarna stämmer och SMS eller MMS i ett annat läge. Kontrollera vad skrivfältet visar inför utskicket. Att äldre meddelanden i tråden hade läskvitton betyder inte att nästa meddelande säkert skickas på samma sätt."],
  "begrepp-rcs-klient": ["Appen påverkar upplevelsen", "Klienten bestämmer hur text, media och val presenteras på skärmen inom det stöd som finns. Uppdateringar, textstorlek och inställningar kan därför ändra upplevelsen även när avsändaren skickar samma innehåll. För företag innebär det att en förhandsvisning behöver kompletteras med telefonprov. Viktiga besked ska vara begripliga även när en bild beskärs eller en knapp visas på en annan plats."],
  "begrepp-rich-card": ["Samla det som hör ihop", "Kortet är ett innehållsformat, inte en egen webbsida. Det passar när bild och kort text förklarar samma produkt, tid eller besked. Låt knappen ta kunden vidare till en relevant handling och skriv det väsentliga så att bilden inte ensam bär informationen. Om flera kort behövs kan en karusell användas, men fler delar gör inte automatiskt meddelandet tydligare."],
  "begrepp-skrivindikator": ["Närvaro utan löfte om svar", "Indikatorn kan hjälpa deltagarna att förstå att någon är aktiv, men det som skrivs kan ändras eller aldrig skickas. Den ska därför inte användas som grund för att stänga ett ärende eller anta att kunden accepterat något. I ett företagsflöde behöver verkliga inkommande svar behandlas separat. Bemanning och utlovad svarstid bör också framgå oberoende av indikatorn."],
  "begrepp-sms": ["En enkel reserv behöver eget innehåll", "SMS är användbart för ett kort besked när meddelandet inte behöver ett rikt format. En vanlig webblänk kan leda vidare, men den är inte samma sak som en inbyggd RCS-åtgärd. Kontrollera textens kodning och längd innan ni räknar kostnad. Om SMS används som reserv ska kunden ändå kunna förstå ärendet utan att ha sett RCS-versionen."],
  "begrepp-webhook": ["Händelser måste tas om hand", "Webhooken är mottagningsadressen, medan verksamhetsreglerna finns i systemet bakom den. Ett inkommande svar kan exempelvis registreras först och sedan skickas till rätt kö eller order. Planera vad som händer om behandlingen misslyckas efter mottagningen. Återleveranser behöver kunna kännas igen så att en tillfällig störning inte leder till flera bekräftelser eller dubbla ändringar."],
  "rcs-sverige-operatorer": ["Bygg en användbar stödbild", "Dela upp frågan i privat Android-chatt, privat iPhone-chatt och företagsmeddelanden. De tre svaren kan skilja sig för samma kund. När en supportuppgift är oklar, notera källa och vilken telefon eller linje beskedet gäller. För planerade utskick är ett test från den registrerade avsändaren till ett relevant mottagarurval mer användbart än att summera operatörernas allmänna lanseringsnyheter."],
  "rcs-tele2": ["När ett abonnemang behöver kontrolleras", "Om stödet är beskrivet men inte syns på telefonen behöver felsökningen bli mer specifik. Ange modell, systemversion och om problemet gäller ett visst samtal eller själva RCS-inställningen. Ett test mellan två telefoner kan visa var skillnaden ligger. Undvik att dra slutsatser om alla Tele2-kunder från ett enda test, särskilt när företagsmeddelanden är det egentliga användningsfallet."],
  "rcs-comviq": ["Testa ditt nummer, inte nätets rykte", "Comviqs egen information är den relevanta utgångspunkten även när samma nät används av andra varumärken. Om du har bytt SIM eller telefon kan nummerregistreringen behöva kontrolleras innan problemet kopplas till operatörsstöd. Se först vilken status appen visar. För företag ska ett lyckat privattest följas av kontroll från den faktiska företagsavsändaren till samma mottagare."],
  "rcs-telia-kontroll": ["Ställ en fråga som går att besvara", "Be om besked för ditt abonnemang, telefonmodell och systemversion, och säg uttryckligen att du menar privat RCS i meddelandeappen. Fråga vad du bör se i inställningarna om det är aktiverat. Om svaret gäller en annan tjänst eller marknad har din fråga inte besvarats. En saknad markering i en extern lista ska inte ersätta ett aktuellt besked om din linje."],
  "rcs-telenor-kontroll": ["Skilj stöd från ett lokalt fel", "Om operatören bekräftar stöd kan nästa kontroll vara appens status och vilken linje telefonen använder. Om stödet inte bekräftas hjälper det däremot inte att fortsätta växla samma inställning. Be att få veta om beskedet gäller iPhone, Android eller båda. Det minskar risken att en generell uppgift om RCS feltolkas som stöd på en viss telefon."],
  "rcs-tre-kontroll": ["Spara förutsättningarna för testet", "Notera vilken telefon och vilket abonnemang som testats samt vilken kanal skrivfältet visar. Då går resultatet att jämföra med operatörens besked utan att blanda ihop olika linjer. Ett lyckat Android-samtal säger inte ensamt något om iPhone. Om ert mål är ett företagsutskick ska även agent och innehållstyp ingå i testbeskrivningen."],
  "rcs-lagprisoperator": ["Samma nät betyder inte samma tjänst", "Operatörens namn på abonnemanget är mer relevant än vilket nät en täckningskarta visar. Tjänstevillkor och aktivering kan skilja sig mellan varumärken. Fråga särskilt om iPhone-stöd och det abonnemang du använder. För Android kan appens anslutningsstatus ge ett konkret test, men ett positivt privattest besvarar fortfarande inte frågan om räckvidd från en registrerad företagsagent."],
  "rcs-apple-operator-uppgifter": ["Redovisa skillnaden i stället för att gissa", "Två supportsidor kan beskriva olika omfattning eller ha uppdaterats vid olika tillfällen. Spara den exakta formuleringen och datumet för kontrollen innan du jämför dem. Om ena sidan handlar om iPhone och den andra om RCS generellt är uppgifterna inte direkt jämförbara. Vid kvarstående osäkerhet bör artikeln säga vad som är bekräftat och hänvisa abonnemangsfrågan till operatören."],
  "rcs-operator-byte": ["Låt den nya linjen bli utgångspunkt", "Efter ett operatörsbyte kan telefonnumret vara oförändrat medan abonnemangets tjänster ändrats. Kontrollera därför RCS-status på den nya linjen och prova ett nytt samtal när bytet är genomfört. Gamla meddelanden visar hur tjänsten fungerade tidigare, inte vad som nu är aktivt. Om registreringen står still behöver supporten veta när bytet skedde och vilken status appen visar."],
  "rcs-sim-byte": ["Kontrollera vilket nummer som registreras", "Ett nytt SIM kan påverka vilken linje appen försöker använda även om telefonen är densamma. Titta därför på numret i RCS-inställningarna och om vanlig telefoni och SMS fungerar efter bytet. Om registreringen inte blir klar, följ appens officiella hjälp i stället för att göra många ändringar samtidigt. Då blir det också lättare att beskriva problemet för supporten."],
  "rcs-dubbla-sim": ["Testa en linje i taget", "När telefonen har två abonnemang behöver du veta vilket nummer det aktuella samtalet använder. Standardlinjen för mobildata är inte i sig bevis på vilken RCS-identitet som används. Stödet för dubbla linjer beror på app och version. Dokumentera därför varje linjes status och prova ett samtal med ett känt RCS-nummer innan du tolkar resultatet som ett operatörsproblem."],
  "rcs-saknad-installning": ["Saknat val och avstängt val är olika", "Om inställningen inte finns är första frågan om operatören erbjuder funktionen för linjen, inte hur man slår på den. Kontrollera också systemversionen och vilken linje som är vald. Om valet finns men samtalet går som SMS behöver även mottagarens stöd undersökas. Den skillnaden hjälper supporten att välja rätt felsökning och undvika onödiga återställningar."],
  "rcs-fastnar-verifiering": ["Gör felsökningen spårbar", "Skriv ned statusen som faktiskt visas och kontrollera vilket nummer appen försöker registrera. Om du nyligen flyttat numret eller bytt enhet är det viktig information. Gör en förändring i taget enligt Googles hjälp så att resultatet går att förstå. Ett verifieringsproblem är inte samma sak som att en viss kontakt saknar stöd, och de två problemen ska felsökas olika."],
  "rcs-vissa-kontakter": ["Jämför två samtal, inte hela telefonen", "När ett samtal fungerar med RCS och ett annat inte gör det har du redan ett tecken på att din egen anslutning kan fungera. Fråga den andra kontakten vilken app och status den har, och kontrollera kanaltexten i båda samtalen. Ett saknat läskvitto är inte ensamt bevis på SMS eftersom rapporteringen kan påverkas av inställningar."],
  "rcs-meddelandekanal": ["Titta före och efter utskicket", "Skrivfältet kan visa vilken kanal appen tänker använda. Efter utskicket kan meddelandedetaljer ge ytterligare information, beroende på appen. Bilder och gröna bubblor är mindre säkra ledtrådar eftersom andra kanaler också kan visa dem. För felsökning är det bra att notera den exakta kanaltexten i stället för att beskriva meddelandet som ett vanligt SMS eller ett bildmeddelande."],
  "rcs-iphone-grona-bubblor": ["Färgen berättar bara en del", "En grön tråd kan bära RCS i ett samtal och SMS eller MMS i ett annat. Därför ska färgen inte användas som en tillgänglighetskontroll eller som bevis på att RCS slutat fungera. Läs kanaltexten och kontrollera mottagarens stöd. Om du hjälper någon annan med felsökning är en beskrivning av den texten mer användbar än enbart bubblans färg."],
  "rcs-roaming": ["Uppkoppling och avgift behöver skiljas åt", "Wifi kan ge internetanslutning utan att du använder mobil roamingdata, men tjänstens övriga förutsättningar behöver fortfarande stämma. Med mobildata beror kostnaden på abonnemanget och landet. Kontrollera därför både datavillkor och RCS-status. Om appen använder SMS som reserv kan andra avgifter gälla; ett lyckat RCS-test hemma är inte en prisuppgift för en utlandsresa."],
  "rcs-kontantkort": ["Be om besked för kontantkortet", "Ett generellt operatörsbesked kan avse andra abonnemang än ditt. Kontrollera att numret är aktivt och fråga om RCS för just kontantkortet och telefonen. RCS använder internet, så tillgången till wifi eller data spelar också roll. Håll eventuella SMS-avgifter åtskilda från dataanvändningen, särskilt om appen kan använda en annan kanal när RCS inte fungerar."],
  "rcs-flytta-telefon": ["Historik och anslutning flyttas inte på samma sätt", "Att gamla meddelanden syns på den nya telefonen betyder inte att RCS är anslutet där. Kontrollera numret och appens status, och följ den officiella flytthjälpen om den gamla enheten fortfarande är kopplad. Skicka sedan ett nytt test till en kontakt med stöd. Bedöm den nya leveransen, inte bara hur tidigare RCS-meddelanden visas efter överföringen."],
  "rcs-avaktivera": ["Vad avstängningen inte gör", "Att stänga av RCS ändrar hur framtida meddelanden kan skickas, men tar inte tillbaka meddelanden som redan har nått någon annan. SMS och MMS kan fortfarande användas när deras förutsättningar finns. Om du byter app eller lämnar en gammal telefon bör du följa tjänstens instruktioner för numret så att meddelanden inte fortsätter kopplas till en registrering du inte längre använder."],
  "rcs-foretagsmeddelanden-iphone": ["Skilj mellan företag och privata kontakter", "Apple beskriver ett separat val för företagsmeddelanden där funktionen är tillgänglig. Läs vad valet påverkar innan du använder den bredare inställningen för all RCS. Att stoppa företags-RCS i telefonen är inte nödvändigtvis samma sak som att avregistrera sig från ett företags reklamlista i andra kanaler. Om du vill stoppa all marknadsföring behöver företaget också få det beskedet."],
  "rcs-blockera-foretag": ["Blockering och avregistrering har olika räckvidd", "Blockering i appen kan hjälpa mot fortsatta meddelanden där, medan en invändning till företaget kan behövas för reklam i andra kanaler. Kontrollera vad appen anger när du blockerar eller rapporterar. Om ett meddelande ser bedrägligt ut bör du inte öppna länken för att hitta hjälp. Använd företagets kända webbplats eller en kontaktväg du hittat oberoende av meddelandet."],
  "rcs-gruppchatt": ["Gruppen behöver bedömas som helhet", "Funktionerna i en grupp kan skilja sig från ett enskilt samtal eftersom alla deltagarnas förutsättningar spelar in. Kontrollera vad appen visar för den aktuella gruppen innan du räknar med läskvitton eller mediedelning. Om en deltagare byter telefon kan läget ändras. Ett privattest i en grupp är heller inte en modell för hur en registrerad företagsagent skickar till en kundlista."],
  "rcs-supportunderlag": ["Ge supporten en avgränsad händelse", "Beskriv när felet inträffade, vad du försökte göra och vilken status eller kanaltext som visades. Ett enda konkret exempel är lättare att följa än att RCS ibland känns trasigt. Skilj ett misslyckat registreringsförsök från ett problem med en kontakt. Dela inte hela privata konversationer i onödan; välj uppgifter som behövs för att förstå anslutning, enhet och abonnemang."],
  "rcs-webhook-avsandarkontroll": ["Kontrollera innan något ändras", "Ett anrop kan innehålla välformade uppgifter och ändå komma från fel avsändare. Verifieringen behöver därför ske innan kundärenden eller leveransstatus uppdateras. Följ den metod som er leverantör dokumenterar och planera även byte av nycklar eller andra verifieringsuppgifter. Logga att kontrollen misslyckades utan att exponera hemligheter eller hela kundmeddelanden i felsökningsmaterialet."],
  "rcs-dubbla-handelser": ["Gör behandlingen säker att upprepa", "Om samma leveranshändelse kommer två gånger ska resultatet normalt bli en leveransstatus, inte två nya kundaktiviteter. Spara en stabil identifierare för händelsen eller den handling ni behandlar. Samma princip gäller kundsvar som ändrar en bokning. Kontrollera också samtidighet: två kopior som kommer nära varandra får inte båda genomföra ändringen innan någon har hunnit markera den som klar."],
  "rcs-webhook-omsandning": ["Mottagning och verksamhetsarbete kan skiljas åt", "Tjänsten behöver få rätt svar på webhook-anropet enligt sina regler, medan tyngre behandling kan fortsätta i ert system. Om en extern ordertjänst är långsam ska det inte automatiskt orsaka flera identiska orderändringar. Bestäm vad som sparas vid mottagningen och vad som kan försöka igen senare. Övervaka även händelser som fastnar så att ett tekniskt accepterat svar inte döljer ett obehandlat kundärende."],
  "rcs-handelser-ordning": ["Låt statusmodellen tåla sena rapporter", "Om en äldre leveransrapport behandlas efter en läsrapport ska den inte göra meddelandet oläst igen. Spara händelsernas egna tider och definiera vilka övergångar som är tillåtna. Behåll gärna historiken för felsökning i stället för att bara skriva över senaste värdet. För affärshändelser, som en ombokning, behövs dessutom kontroll av ärendets aktuella läge innan något ändras."],
  "rcs-handelser-ko": ["Kön hjälper bara om den följs upp", "En kö kan skilja snabb mottagning från arbete som tar längre tid och ge utrymme för återförsök. Men ett accepterat meddelande kan fortfarande fastna i kön. Följ därför köålder och misslyckad behandling, inte bara antalet mottagna anrop. Kundens fråga behöver nå rätt personal eller system även när ett av stegen har haft en tillfällig störning."],
  "rcs-meddelandeidentifierare": ["Behåll kopplingen hela vägen", "Knyt meddelande-id till den interna ordern eller ärendet när utskicket skapas. Telefonnumret räcker inte eftersom samma kund kan ha flera aktiva beställningar. När en status eller ett svar kommer tillbaka går det då att hitta rätt sammanhang. Undvik att lägga känsliga kunduppgifter direkt i identifieraren; använd en referens som bara behöriga system kan slå upp."],
  "rcs-loggning": ["Logga så att ett fel går att följa", "En användbar logg visar tid, meddelandereferens, vilket steg som kördes och resultatet. Den behöver inte innehålla hela meddelandets text eller kundens filer. Skilj fel i utskicksanropet från fel i återrapporteringen. Med en sammanhängande referens kan supporten följa ett ärende utan att bredare loggåtkomst samtidigt ger tillgång till onödiga personuppgifter."],
  "rcs-api-nycklar": ["Begränsa både användning och exponering", "En hemlig nyckel ska inte skickas till kundens webbläsare eller ligga i ett publikt kodexempel. Ge integrationen den åtkomst den behöver och håll test och produktion åtskilda där tjänsten tillåter det. Planera hur en exponerad nyckel spärras och ersätts utan att driftkontrollen tappas. Felsökningsloggar ska visa att autentisering misslyckades, inte skriva ut själva hemligheten."],
  "rcs-felaktiga-anrop": ["Återförsök måste ha ett skäl", "Ett anrop med fel mottagarformat eller ogiltigt innehåll blir inte rätt bara för att det skickas igen. Läs feltypen och åtgärda grundorsaken. Tillfälliga fel kan kräva en annan hantering, men även där behöver samma meddelande kännas igen. Om svaret försvinner efter ett anrop måste integrationen kunna undersöka läget utan att automatiskt skapa ett dubbelt kundbesked."],
  "rcs-telefonnummer-format": ["Normalisera innan utskicket skapas", "Ett nummer från ett kalkylblad kan innehålla mellanslag, lokalt format eller saknad landskod. Bevara inte det som en gissning i utskicksanropet utan kontrollera och normalisera enligt tjänstens dokumentation. Ett tekniskt giltigt nummer säger ändå inget om kontaktregler eller RCS-stöd. De behöver prövas separat, så att nummerkontrollen inte blir ett obefogat godkännande av mottagarlistan."],
  "rcs-giltighetstid": ["Aktualiteten hör till ärendet", "En påminnelse och ett allmänt leveransbesked kan behöva olika tidsgränser. Utgå från när kunden fortfarande har nytta av informationen, inte från en bekväm standardinställning. När beskedet har gått ut behöver även eventuella återförsök och reservkanaler respektera gränsen. Annars kan en tekniskt lyckad leverans ge ett felaktigt råd, exempelvis att komma till en tid som redan passerat."],
  "rcs-avbryta-vantande": ["Kontrollera vad som faktiskt stoppades", "En begäran om att stoppa ett väntande meddelande behöver följas av det svar eller den status som tjänsten dokumenterar. Meddelandet kan redan ha gått vidare eller levererats. Skilj därför begärd avbrytning från bekräftad avbrytning. Om syftet är att skicka SMS i stället behöver den skillnaden ingå i reservlogiken så att kunden inte får samma besked genom två kanaler."],
  "rcs-reserv-dubbla-besked": ["Samordna kanalbesluten", "Beslutet att skicka SMS och uppföljningen av väntande RCS ska höra till samma ärende. Om olika system fattar beslut oberoende av varandra kan båda tro att de behöver skicka. Registrera vilken kanal som valts och hur senare statusar hanteras. Testa särskilt fallet där RCS-rapporten kommer precis när reserven startar; det är där en enkel tidsregel ofta blir otillräcklig."],
  "rcs-inkommande-filer": ["Ta inte emot mer än ni kan hantera", "En kund kan skicka ett foto eller dokument som innehåller mer information än ärendet behöver. Kontrollera filtyp och hantera innehållet med lämpligt skydd innan personalen öppnar det. Bestäm vart filen ska sparas och hur länge. Om tjänsten inte kan behandla formatet ska kunden få ett begripligt besked och en fungerande alternativ väg, inte bara ett tyst misslyckande."],
  "rcs-ovantade-svar": ["Fritext är en del av verkligheten", "Kunden kan skriva något annat än det ni förberett på knapparna eller svara på ett äldre besked. Flödet behöver därför kunna känna igen sammanhang utan att anta att varje text är en giltig orderändring. Be om förtydligande när det behövs och lämna vidare till personal vid osäkerhet. Ett automatiskt standardsvar är inte tillräckligt om kunden faktiskt beskriver ett nytt problem."],
  "rcs-delad-plats": ["Platsen behöver ett ändamål", "En delad plats kan hjälpa till med ett leverans- eller serviceärende, men ska inte automatiskt kopieras till alla kundsystem. Kontrollera vilket ärende den gäller och vem som behöver uppgiften. Bekräfta också om platsen är tillräcklig för uppgiften eller om en adress fortfarande krävs. Undvik att beskriva mottagen plats som en färdig bokning eller en bekräftad leveranspunkt innan det är kontrollerat."],
  "rcs-varumarken-agenter": ["Utgå från vad kunden känner igen", "Om kunden handlar från två olika varumärken kan en gemensam okänd avsändare göra beskeden svårare att förstå. Diskutera profil och registrering med partnern utifrån den faktiska kundkontakten. Samtidigt behöver interna system kunna koppla varje utskick till rätt verksamhet. Fler agenter ger inte automatiskt bättre struktur om svar och kontaktuppgifter ändå hamnar på fel ställe."],
  "rcs-lanseringsunderlag": ["Gör godkännandet möjligt att slutföra", "Uppgifterna ska vara konsekventa mellan profil, webbplats och den behöriga representanten. Om olika namn eller gamla kontaktvägar används kan processen behöva förklaringar. Be partnern tydliggöra vilka delar som återstår och vilka marknader ansökan avser. Planera inte kundutskickets datum enbart efter att formuläret är ifyllt; den faktiska lanseringsstatusen behöver vara klar."],
  "rcs-testagent-produktion": ["Testresultatet har en begränsad räckvidd", "En testagent kan visa hur innehållet ser ut på inbjudna testtelefoner, men bevisar inte att agenten får kontakta vanliga kunder. Dokumentera vad testet faktiskt omfattade och kontrollera publik lansering separat. Samma skillnad gäller rapporteringen: att en testtelefon gav ett läskvitto betyder inte att hela målgruppen senare rapporterar likadant. Test och produktionsgodkännande svarar på olika frågor."],
  "rcs-automatiska-svarstider": ["Ett snabbt autosvar är inte ett snabbt ärende", "Om personalen svarar nästa vardag ska ett automatiskt mottagningsbesked säga det i stället för att antyda pågående hjälp. Ange vad kunden kan göra när frågan är brådskande. Följ upp faktisk väntan till ett användbart svar och när ärendet löstes. Då blir det tydligt om automatiseringen hjälper kunden eller bara gör det första tekniska svaret snabbare."],
  "rcs-kort-medieadress": ["Filen måste vara åtkomlig när den hämtas", "En bild som fungerar för en inloggad medarbetare kan ändå vara otillgänglig för meddelandetjänsten. Kontrollera tjänstens krav på åtkomst, filtyp och storlek samt att adressen inte löper ut för tidigt. Testa med samma publicerade fil som ska användas i utskicket. En lyckad lokal förhandsvisning bevisar inte att mediet kan hämtas av alla delar av leveransflödet."],
  "rcs-kort-beskarning": ["Lämna utrymme runt det viktiga", "Placera inte pris, produktnamn eller nödvändiga detaljer nära bildens ytterkant. Appens visning kan beskära mediet olika beroende på format och skärm. Skriv de avgörande uppgifterna som text i meddelandet och prova bilden på flera enheter. En produktbild ska helst tåla variation utan att det blir oklart vilket alternativ kunden ser eller vad erbjudandet gäller."],
  "rcs-funktion-utan-stod": ["Förenkla utan att ändra betydelsen", "Om en funktion saknas behöver innehållet fortfarande hjälpa kunden med samma uppgift. En karusell kan ersättas av en länk till jämförbara alternativ, medan ett kort kan bli text med en relevant webbadress. Välj vägen utifrån stödkontrollen och tjänstens regler. Ett fel i kontrollen ska behandlas som ett fel, inte som ett säkert besked om att mottagaren saknar funktionen."],
  "rcs-handelser-overvakning": ["Skilj tystnad från låg aktivitet", "Få händelser kan vara normalt om inga meddelanden skickas. Jämför därför återrapporteringen med de utskick och testsvar som borde ge händelser. Kontrollera också fel och köer på mottagningssidan. Ett regelbundet kontrollflöde med känd förväntan kan hjälpa till att upptäcka avbrott, men ska hållas åtskilt från kundstatistiken så att driftprover inte räknas som kampanjresultat."],
  "rcs-saker-aterstart": ["Återuppta från känt läge", "Efter ett avbrott kan vissa meddelanden redan ha skickats medan andra fortfarande väntar. Undersök sparade identifierare och statusar innan hela jobbet startas om. Händelser som behandlas igen ska inte skapa nya orderändringar. Prioritera också aktualitet: ett återställt system ska inte skicka gamla påminnelser bara för att de låg kvar i kön. Återstarten behöver både teknisk och verksamhetsmässig kontroll."],
  "rcs-tillganglighet-textstorlek": ["Låt innehållet tåla mer plats", "Stor text kan ge längre kort och flytta knappar längre ned. Testa därför ett helt meddelande med telefonens större textinställning, inte bara rubriken. Förkorta onödiga formuleringar men behåll villkor och viktiga tider. Innehållet ska gå att förstå utan att kunden behöver jämföra en liten bildtext med en knapp som hamnat utanför det första skärmutrymmet."],
  "rcs-skarm-lasare": ["Texten måste bära ärendet", "Skriv datum, belopp och instruktioner som läsbar text i stället för att bara lägga dem i en bild. Knappnamn som Öppna ordern ger mer information än Klicka här. Testa med den verkliga meddelandeappen och telefonens skärmläsare, eftersom stödet beror på klienten. Även sidan som knappen öppnar behöver fungera; en tillgänglig första text hjälper inte om nästa steg blir omöjligt."],
  "rcs-karusell-forsta-kort": ["Första kortet är inte hela meddelandet", "Det bör ge tillräckligt sammanhang för att kunden ska förstå varför fler alternativ finns. Lägg inte ett avgörande villkor enbart på ett senare kort. Om första kortet visar en produkt ska samma jämförbara uppgifter finnas på de andra. Provskicka och kontrollera vad som syns innan kunden sveper; det är den upplevelsen ni faktiskt inleder med."],
  "rcs-karusell-ordning": ["Välj en begriplig sortering", "Pris, kategori eller relevans kan vara rimliga ordningar, men de bör vara konsekventa och möjliga att förstå. Om korten presenterar olika saker utan gemensamma uppgifter blir bläddringen mest ett letande. Se också till att varje kort kan öppna rätt alternativ direkt. Ordningen kan testas, men dra inte slutsatsen att första kortet är bäst enbart för att det fått flest visningar."],
  "rcs-en-eller-flera-knappar": ["Fler val behöver tydliga skillnader", "Lägg till en knapp när den representerar ett eget användbart nästa steg. Två nästan likadana länkar gör ofta valet otydligare. Ett huvudval kan kompletteras med kontakt eller hjälp om kunden behöver en annan väg. Prova hela meddelandet på telefon och kontrollera att knapparnas betydelser fortfarande är tydliga när texten ovanför är längre än i designutkastet."],
  "rcs-fritext-eller-knappar": ["Ge plats för det ni inte förutsåg", "Knappar passar ett begränsat val, medan fritext behövs när kunden ska beskriva en situation. En dialog kan använda båda utan att låsa användaren till en felaktig kategori. Bestäm vad som händer med text som inte går att tolka säkert. Kunden ska få en begriplig väg till hjälp, inte samma knappmeny igen när problemet redan visat sig ligga utanför den."],
  "rcs-knapp-bekraftelse": ["Bekräfta den verkliga förändringen", "Efter ett val behöver kunden veta om något blev klart eller bara skickades vidare. Hämta resultatet från systemet som äger ärendet innan ett slutligt besked ges. Om en ändring inte längre är möjlig ska svaret förklara nästa steg. Det är särskilt viktigt vid fördröjda svar, eftersom bokningen eller erbjudandet kan ha ändrats mellan meddelandet och knapptrycket."],
  "rcs-sprakversioner": ["Översätt även nästa steg", "Ett svenskt meddelande som leder till en obegriplig sida ger en splittrad upplevelse. Använd kundens kända språkval där det finns ett relevant underlag och håll knapptexter och bekräftelser på samma språk. Om språkuppgift saknas behövs ett genomtänkt standardval. Översätt inte stabila interna referenser på samma sätt som synlig text, annars kan systemet få svårt att känna igen kundens handling."],
  "rcs-prisvillkor-kort": ["Det kunden behöver bedöma ska synas", "Om priset gäller en särskild period eller kräver ett villkor bör det framgå nära erbjudandet. En länk kan ge längre information, men ska inte användas för att dölja något som ändrar huvudbudskapet. Kontrollera även landningssidan så att samma pris och giltighet gäller där. Kunden ska inte behöva öppna flera kort för att förstå vilket erbjudande som faktiskt visas."],
  "rcs-emoji-foretag": ["Ton får inte ersätta information", "Emoji kan passa ett lättsamt besked men ska inte vara enda sättet att ange status eller betydelse. Skriv exempelvis att bokningen är bekräftad i text även om en symbol används. Prova hur meddelandet läses med skärmläsare och på olika telefoner. Vid förseningar, betalningar och fel är ett rakt besked ofta mer hjälpsamt än en extra lekfull markering."],
  "rcs-lanka-ratt-order": ["Rätt länk behöver rätt behörighet", "En orderreferens i adressen ska inte ensam ge obehöriga tillgång till kunduppgifter. Planera hur kunden identifieras och vad som händer om länken öppnas på en annan enhet. Samtidigt bör en nödvändig inloggning leda tillbaka till rätt order, inte startsidan. Testa flera samtidiga beställningar så att en generell senaste-order-länk inte råkar visa fel ärende."],
  "rcs-forhandsvisning-test": ["Telefonprovet visar resten", "Förhandsvisningen hjälper att granska innehåll och form, men testar inte hela leveransen eller systemet bakom knapparna. Provskicka till verkliga enheter och genomför handlingarna. Kontrollera även hur meddelandet ser ut med större text och långsam anslutning. Ett godkänt utkast är en del av kvalitetssäkringen; fungerande länkar, kundsvar och återrapportering behöver sina egna prov."],
  "rcs-sms-lanktext": ["Ge länken ett begripligt ärende", "Skriv varför kunden ska öppna länken och vilken order eller bokning det gäller. En ensam förkortad webbadress kan bli svår att lita på eller skilja från reklam. Kontrollera också SMS-textens längd och kodning när adressen lagts till. Reservversionen ska fungera på egen hand, eftersom kunden kanske aldrig har sett RCS-kortet som länken ersätter."],
  "rcs-bilder-utan-text": ["En bild kan utebli eller bli svårläst", "Långsam anslutning, beskärning och hjälpmedel kan påverka hur bilden uppfattas. Lägg därför inte bokningstid, pris eller villkor enbart i mediet. Skriv kärninformationen i text och låt bilden förklara eller komplettera. Det hjälper också när ett enklare format måste användas. Kunden ska kunna förstå det viktiga beskedet utan att behöva förstora en liten grafisk text."],
  "rcs-video-nar": ["Välj video när rörelsen behövs", "En kort instruktion eller en produkt i användning kan vara lättare att förstå i film än i flera stillbilder. Men en leveranstid eller ett enkelt pris behöver sällan video. Gör budskapet begripligt utan ljud och kontrollera laddningen på telefon. Om kunden måste se filmen för att hitta en grundläggande uppgift har mediet troligen fått för stor roll i beskedet."],
  "rcs-personalisering-namn": ["Ha en fungerande text utan namn", "Kunddata kan vara tom, gammal eller innehålla ett företagsnamn där ni väntat er ett förnamn. Använd bara namn när kvaliteten och sammanhanget är tillräckliga. Skriv en reservhälsning som fungerar utan fältet och prova ofullständiga poster innan utskicket. En korrekt orderreferens hjälper ofta mer än personlig tilltalston; fel namn kan i stället minska förtroendet för hela beskedet."],
  "rcs-igenkanning-lang-dialog": ["Behåll sammanhang när ämnet ändras", "En lång tråd kan innehålla flera beställningar eller frågor. Skriv därför vilken order eller vilket ärende ett nytt besked gäller utan att upprepa hela historiken. Om personal tar över från automatiseringen bör kunden förstå vem som nu svarar. Profilen ger en gemensam identitet, men texten behöver fortfarande skilja ett nytt erbjudande från en uppföljning av en pågående fråga."],
  "rcs-kundresa-utan-app": ["Inkorgen kan vara början", "RCS kan samla besked och ett tydligt nästa steg utan att hela köpet byggs i chatten. En webbsida kan fortfarande vara bättre för inloggning, betalning eller många produktval. Se till att övergången bevarar kundens sammanhang och att det framgår när nästa steg är klart. Färre appinstallationer är en egenskap hos upplägget, inte ett bevis på att varje kundresa blir kortare."],
  "rcs-mansklig-overlamning": ["Överlämna frågan, inte bara kunden", "Personalen behöver se vad kunden redan valt och vilket ärende dialogen gäller. Berätta när överlämningen sker och vad kunden kan förvänta sig under väntan. Om bemanning saknas ska ett annat kontaktalternativ finnas. En bot som fortsätter skicka samma meny samtidigt som en person svarar skapar lätt förvirring, så bestäm vem som äger samtalet efter överlämningen."],
  "rcs-felbudskap-kund": ["Förklara vad kunden kan göra nu", "Kunden behöver sällan en intern felkod, men behöver veta om begäran togs emot och om något ändrades. Om svaret är osäkert ska ni inte uppmana personen att upprepa ett känsligt val utan kontroll. Ge en kontaktväg eller ett säkert återförsök som passar situationen. Håll tekniska detaljer i driftunderlaget och den praktiska konsekvensen i kundens meddelande."],
  "rcs-aterkommande-aviseringar": ["Skicka när informationen förändrar något", "Flera statusändringar i ert system kan betyda samma sak för kunden. Samla dem när det går och prioritera besked som kräver en handling eller ger ny användbar information. Låt mottagarens val styra relevanta återkommande utskick. Följ upp klagomål och blockeringssignaler tillsammans med leveransdata; en hög leveransandel säger inte om kontakten uppskattas."],
  "rcs-tidszon-kampanj": ["Bestäm vilken lokal tid som avses", "Ett utskick som planeras till morgonen behöver kopplas till rätt tidszon och hantera övergången mellan sommar- och vintertid. Följ tjänstens regler för tidsangivelser och spara planeringen så att den går att kontrollera. Testa gränsfall innan återkommande jobb startas. En korrekt lagrad tid är inte tillräcklig om verksamheten och integrationen har olika uppfattning om när kunden ska kontaktas."],
  "rcs-ab-test-ett-val": ["Gör grupperna jämförbara", "Om både målgrupp, erbjudande och knapptext ändras samtidigt går det inte att veta vad som påverkade resultatet. Fördela likvärdiga mottagare och håll uppföljningsperioden densamma. Bestäm ett relevant mått i förväg, till exempel genomförda bokningar. Ett litet test kan ge en riktning men behöver redovisas med sin storlek och osäkerhet, inte presenteras som en allmän RCS-effekt."],
  "rcs-trad-order-besked": ["Identifiera ordern i varje viktigt steg", "Kunden kan ha flera samtidiga beställningar från samma avsändare. En kort referens och rätt spårningslänk hjälper till att skilja beskeden åt. Håll interna leveranshändelser kopplade till samma order så att ett sent statusmeddelande inte ger fel information. Tråden samlar kontakten med företaget, men ska inte användas som ersättning för en tydlig koppling mellan meddelande och ärende."],
  "rcs-ny-kanal-samma-budskap": ["Samma uppgift, olika presentation", "RCS kan visa bilder och knappar medan SMS behöver text och en vanlig länk. Bevara ärende, villkor och nästa steg i båda versionerna, även när formen ändras. Granska dem tillsammans när erbjudandet uppdateras. Om bara den ena versionen får ett nytt pris eller tidsfönster kan reservkanalen ge ett annat besked än huvudkanalen till kunder i samma utskick."],
  "rcs-marknadsforing-invandning": ["Invändningen måste nå hela flödet", "Att markera kunden i ett register hjälper inte om en kopierad kampanjlista fortfarande kan skickas. Stoppa relevanta planerade reklamutskick och säkerställ att anslutna tjänster använder den uppdaterade informationen. Håll skillnaden mellan marknadsföring och nödvändiga servicebesked tydlig. Bekräfta mottagandet begripligt och låt en dataskyddskunnig person bedöma hur underlaget för invändningen ska hanteras."],
  "rcs-svar-inte-samtycke": ["Bedöm vad kunden faktiskt valde", "Ett svar på en bokningsfråga eller ett klick för att spåra ett paket beskriver just den handlingen. Det är inte automatiskt ett godkännande av nya erbjudanden. Om ni ber om ett marknadsföringsval behöver innebörden vara tydlig och dokumentationen visa vilket val som gjordes. Teknisk knappdata kan hjälpa att registrera händelsen, men ersätter inte bedömningen av kontaktreglerna."],
  "rcs-marknadsforing-avsandare": ["Profilen ersätter inte reklamidentifiering", "Ett företagsnamn visar vem samtalet kommer från men berättar inte alltid att ett visst meddelande är reklam. Utforma innehållet så att syftet och avsändaren går att förstå. Se också över vart länken leder och att erbjudandet stämmer där. Ett serviceutseende bör inte användas för att dölja ett reklambudskap; bedöm textens verkliga innehåll och sammanhang."],
  "rcs-transaktion-reklam": ["Bedöm tillägget separat", "Ett orderbesked behövs för köpet, medan ett nytt erbjudande kan ha ett annat syfte och andra kontaktförutsättningar. Att lägga dem i samma kort gör inte skillnaden mindre. Granska vilken information som är nödvändig för ärendet och vad som är marknadsföring. Vid osäkerhet är det bättre att hålla flödena tydligt åtskilda och få rättslig bedömning än att anta att hela meddelandet är service."],
  "rcs-avregistrering-leverantor": ["Ha en gemensam källa för kontaktval", "Om flera tjänster skickar behöver de få samma besked om en invändning. Kontrollera även exporterade listor och schemalagda jobb som skapats innan valet ändrades. Testa med en kontrollerad kontakt att stoppet får effekt överallt där reklam kan skickas. En lyckad avregistrering i en enskild portal visar inte att de andra leverantörerna eller manuella utskicken har uppdaterats."],
  "rcs-dataminimering": ["Utgå från vad ärendet kräver", "Ett leveransbesked kan behöva telefonnummer och orderreferens utan att hela kundprofilen följer med till meddelandetjänsten. Kartlägg vilka fält som skickas, sparas och syns för personal. Ta bort onödiga uppgifter innan de lämnar ursprungssystemet. Hur mycket data som behövs beror på syftet; IMY:s information om invändningar är viktig men är inte ensam en fullständig vägledning för denna bedömning."],
  "rcs-lagring-kundsvar": ["Sätt tid efter syfte, inte vana", "Kundsvar kan behövas under ett pågående ärende men ska inte automatiskt ligga kvar för alltid i flera system. Bestäm vem som ansvarar för gallring och hur kopior i export, loggar och leverantörstjänster hanteras. En enda generell tidsgräns passar inte nödvändigtvis alla uppgifter. Dokumentera behovet och få en dataskyddsbedömning i stället för att anta att meddelandekanalens standardinställning är tillräcklig."],
  "rcs-support-atkomst": ["Åtkomst ska följa arbetsuppgiften", "Den som felsöker leverans kanske behöver status och identifierare men inte hela kundens dokument. Separera därför driftuppgifter från innehåll där det är möjligt och låt ansvariga team se relevant material. Planera även vad som händer när personal byter roll. Kanalens åtkomstregler är bara en del; kopior i ärendesystem och exporter behöver samma genomtänkta hantering."],
  "rcs-kansliga-uppgifter": ["Styr vidare utan att sprida innehållet", "Om kunden skickar mer känslig information än ärendet behöver ska den inte automatiskt återges i autosvar eller breda loggar. Bedöm vem som måste hantera den och ge kunden en lämplig skyddad väg vid behov. Privat RCS-kryptering säger inget säkert om skyddet i företagets inkorg eller lagring. Hanteringen behöver därför utgå från uppgifterna och de verkliga systemen."],
  "rcs-statistik-senare": ["Använd samma uppföljningstid", "Leverans- och läshändelser kan komma efter att den första rapporten har hämtats. Om två kampanjer mäts vid olika tidpunkter blir jämförelsen missvisande. Spara därför rapporttid och definiera när resultatet betraktas som tillräckligt moget. Separera sena kanalhändelser från bokningar eller köp som också kan ske senare. De förändrar olika delar av analysen och ska inte blandas ihop."],
  "rcs-klick-konvertering": ["Koppla ihop händelser utan att överdriva", "Ett klick kan öppna sidan utan att kunden slutför något. Mät därför den önskade handlingen där den sker och definiera hur den kopplas till utskicket. Hantera upprepade klick och samma köp så att de inte blir flera resultat. Redovisa också om kopplingen är osäker. Kanalens rapport och orderregistrets data är två olika underlag, inte två namn på samma mått."],
  "rcs-sms-matt-jamforelse": ["Välj ett gemensamt slutmått", "RCS-läsningar och SMS-leveranser beskriver olika steg och bör inte ställas mot varandra som likvärdiga resultat. Ett genomfört köp eller en bokning kan vara mer jämförbart om erbjudande och målgrupp hålls lika. Redovisa vilka kanalhändelser som finns och saknas. Då går det att se både skillnader i rapportering och verkliga skillnader i kundernas handlingar utan att blanda ihop dem."],
  "rcs-serviceteam-matning": ["Mät hjälp, inte bara aktivitet", "Många meddelanden eller snabba autosvar säger lite om kundens problem blev löst. Följ tid till användbart svar, lösning och eventuell ny kontakt om samma ärende. Skilj automatiska besked från personalens arbete. Läs också ett relevant urval av ärenden kvalitativt, med lämplig åtkomst, så att rapporten inte belönar en dialog som ser snabb ut men lämnar kunden med samma fråga."],
  "rcs-kostnad-reservkanal": ["Räkna kanalerna var för sig", "Utgå från hur många meddelanden av varje typ som faktiskt debiteras och vilka som går vidare till reserven. Leveransrapporter kan hjälpa att följa flödet men ersätter inte tjänstens prisvillkor. Stäm av fakturaunderlaget och ange om kostnaden även innehåller integration eller hantering. Ett genomsnitt per kontakt kan annars dölja att samma kund fått flera meddelanden eller att reservkostnaden räknats dubbelt."],
  "rcs-debitering-status": ["Teknisk status och betalningsregel är olika", "En faktura kan bygga på andra regler än den status ni visar i ett kundärende. Be leverantören förklara vad som debiteras vid accepterat anrop, fel och eventuell reservkanal. Koppla underlagen med identifierare där det går, men behåll de olika definitionerna. Om rapporterna inte stämmer behöver skillnaden undersökas, inte döljas genom att alla statusar döps om till debiterat."],
  "rcs-pilot-mottagare": ["Låt urvalet pröva de verkliga riskerna", "Börja med mottagare ni får kontakta och som representerar de telefoner och kundärenden ni behöver klara. Lägg till kontrollerade testfall utan stöd och med fördröjda svar. Ett urval av enbart medarbetare med samma telefon kan ge en alltför positiv bild. Dokumentera vilka som ingick och vilka situationer som saknas innan pilotens resultat används för att planera ett större utskick."],
  "rcs-pilot-avbryta": ["Bestäm stoppkriterier före starten", "Fel mottagare, trasiga länkar och dubbla ändringar är exempel på avvikelser som kan kräva paus innan fler kunder påverkas. Utse vem som får fatta beslutet och hur schemalagda meddelanden stoppas. Låg klickandel är en annan typ av signal än ett säkerhetsfel. Efter en paus ska ni kunna skilja redan skickade meddelanden från väntande jobb innan piloten återupptas."],
  "rcs-upphandling-fragor": ["Be om svar som kan provas", "En demonstration av ett snyggt kort besvarar inte frågor om leverans, kundsvar eller drift. Be leverantören visa hur ert planerade innehåll fungerar för relevanta mottagare och hur ett fel hanteras. Villkor för debitering och reservkanal ska vara tydliga innan kalkylen görs. Skilj mellan vad som ingår nu, vad som kräver kontoaktivering och vad som bara finns på en framtidsplan."],
  "rcs-rackvidd-foretagsiphone": ["Testa från rätt avsändare", "Ett privat RCS-samtal på iPhone visar att just det samtalet fungerar. För företagsräckvidd behöver testet använda den lanserade agenten, relevant innehåll och mottagare med olika abonnemang. Spara kapabilitetsresultat och leveranshändelser som separata uppgifter. Ett litet test kan verifiera specifika kombinationer, men ska inte redovisas som en täckningsandel för alla svenska iPhone-användare."],
  "rcs-operatornyhet-tolka": ["Läs omfattningen bakom rubriken", "En lanseringsnyhet kan gälla privat chatt, ett land, en app eller vissa abonnemang. Kontrollera de begränsningarna innan nyheten blir ett påstående om er kundräckvidd. Se om företagsavsändare nämns uttryckligen och följ upp med aktuell supportinformation. Ett framtida införande är inte samma sak som stöd idag, och ett marknadsföringspåstående behöver fortfarande konkret underlag för de mottagare ni vill nå."],
  "rcs-agent-profil-andring": ["Kontrollera mer än bilden", "Vid nytt namn eller logotyp behöver även länkar, supportadress och registreringsuppgifter stämma med kundens förväntningar. Fråga partnern om ändringen påverkar verifiering eller lansering. Provskicka sedan så att den publika profilen granskas, inte bara redigeringsvyn. Gamla meddelanden och nya besked kan finnas i samma tråd, så förklara ett större varumärkesbyte när kunden annars riskerar att bli osäker."],
  "rcs-avdelningar-samma-avsandare": ["Samordna kontakten bakom profilen", "En gemensam avsändare kan ge igenkänning, men teamen behöver veta vem som ansvarar för svar och vilka kontaktval som gäller. Ett kampanjutskick får inte lämna supporten med frågor de saknar underlag för. Om flera agenter används ska uppdelningen vara begriplig för kunden. Organisationsschemat behöver inte visas i inkorgen; en tydlig ärendehantering är viktigare än att varje avdelning får egen profil."],
  "rcs-kundlistor-import": ["En ren lista är mer än rätt format", "Kontrollera dubbletter, aktuella nummer och vilka kontakter som får ingå i just utskickets syfte. En export kan vara äldre än senaste invändningen, så avstämning behöver ske mot aktuella kontaktval. Bevara spårbarhet till listans ursprung utan att föra över mer persondata än nödvändigt. Ett lyckat filimporttest visar bara att posterna kan läsas, inte att de får användas."],
  "rcs-kundreferenser-pastanden": ["Skilj logotyp från uppmätt resultat", "En kundlogotyp visar en relation när användningen är tillåten, men är inte ett belägg för en viss klickandel eller försäljningsökning. För resultatpåståenden behövs underlag, period, urval och måttdefinition. Beskriv ett enskilt utfall som just ett enskilt utfall. Om jämförelsen saknas ska ni inte skriva att RCS orsakade förbättringen. Publicering behöver också stämmas av med kunden."],
  "rcs-statusuppdatering-rutin": ["Spara vad som förändrades", "En rutin för operatörsinformation bör notera källa, kontrolltid och vilket användningsfall uppgiften gäller. Om två originalkällor skiljer sig ska det framgå tills skillnaden kan förklaras. Uppdatera inte bara ett ja eller nej utan även begränsningarna. För företags-RCS behöver dokumentationen kompletteras med tester från den egna agenten, eftersom allmän konsumentsupport inte redovisar den räckvidden."],
  "rcs-test-mellan-operatorer": ["Håll kombinationerna tydliga", "Testa ett nytt meddelande i varje riktning och notera telefon, app, abonnemang och kanaltext. Ett lyckat test i en kombination säger inte att alla telefoner i samma nät fungerar likadant. Om någon byter app eller linje behöver testet beskrivas på nytt. Redovisa bara de kombinationer som faktiskt provats, och håll privata samtal åtskilda från tester av företagsavsändare."],
};

export const articleDepth: Record<string, ArticleDepth> = Object.fromEntries(
  Object.entries(prose).map(([slug, [heading, paragraph]]) => [slug, { heading, paragraphs: [paragraph] }]),
);